// platform — explicit file-association registration (CO-1).
//
// Registration is a deliberate command (`--register-file-types`), never a
// startup side effect. Windows writes HKCU classes, Linux writes a user .desktop
// file plus mimeapps.list, and macOS reads the document types from the app
// bundle's Info.plist generated by packaging.

#pragma once

#include <QString>
#include <QStringList>

namespace koalaamp::platform {

struct FileAssociationResult {
    bool ok{false};
    QString error;
    QStringList details;
};

/// Audio plus playlist extensions this build can consume.
QStringList mediaExtensions();

/// MIME type for an extension (without the dot). Empty when unknown.
QString mimeTypeForExtension(const QString& extension);

/// Deterministic desktop-entry text (public for tests).
QString linuxDesktopEntry(const QString& executable, const QStringList& extensions);

/// Windows command strings (`--play` / `--enqueue`), public for tests.
QString windowsPlayCommand(const QString& executable);
QString windowsEnqueueCommand(const QString& executable);

/// Applies or removes the user-level associations. On macOS this returns an
/// error explaining that the bundle Info.plist owns them.
FileAssociationResult registerFileAssociations(const QString& executable, bool unregister);

} // namespace koalaamp::platform
